import{_ as s,l as o,o as e,c as n,v as t,p as l,x as r,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"传输门与三态","description":"","frontmatter":{"title":"传输门与三态","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/transmission-tristate.md","filePath":"cs/transmission-tristate.md","lastUpdated":1789023840000}'),h={name:"cs/transmission-tristate.md"};function c(A,a,_,m,B,u){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="传输门与三态" tabindex="-1">传输门与三态 <a class="header-anchor" href="#传输门与三态" aria-label="Permalink to &quot;传输门与三态&quot;">​</a></h1><div class="epigraph"><p>互补 CMOS 门总要把输出钉在轨上；传输门把通路打开或切断，三态则允许把线让给别人驱。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/nand-universal">与或非与万能门</a>钉死了 NAND/NOR 能拼任意布尔函数。本课不重证完备，也不从模拟开关电阻另起。缺口是：后课总线、寄存器旁路、多路选择，经常需要<strong>不驱动</strong>某根线，而不是再做一个总在推 0/1 的门。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态 CMOS 输出在稳态靠近电源或地，两块若接到同一节点会对打。缺口是两种受控连接：传输门（nMOS+pMOS 并联，栅相反）导通时近似双向通路；三态缓冲在使能无效时输出高阻 \\(Z\\)，使能有效时等同普通缓冲。多驱动线必须互斥使能，否则争用。</p><p>本课只钉通路与高阻。延迟、负载计入<a href="/cs/gate-delay">下一课</a>。MUX 可用传输树或门级，后课再命名。</p><h3 id="高阻不是「第三种逻辑-1」" tabindex="-1">高阻不是「第三种逻辑 1」 <a class="header-anchor" href="#高阻不是「第三种逻辑-1」" aria-label="Permalink to &quot;高阻不是「第三种逻辑 1」&quot;">​</a></h3><p>\\(Z\\) 表示没人推，线上电压由电容保持或被别人驱，不是合法数字值。把三态当 ternary 逻辑，后课总线会把浮空当数据。传输门导通时两端都应是强 0/1，弱电平经传输管会再衰减。</p><p><span class="marginnote">Harris 用传输门做小型 MUX，用三态做总线。本课不把动态逻辑、多米诺当主干。双向引脚是三态的封装形态，协议仍是互斥驱动。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>传输门：两管互补开启，通过强 0 与强 1。三态：使能与数据经与非/或非再接到互补输出级，或输出级本身可关断。总线：若干三态接同一节点，译码保证同一时刻至多一个有效。</p>',11)),(e(),l(E,null,{default:r(()=>[p(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAND%5B%22%E9%9D%99%E6%80%81%20CMOS%20%E9%97%A8%22%5D%20--%3E%20TG%5B%22%E4%BC%A0%E8%BE%93%E9%97%A8%EF%BC%9A%E5%8F%97%E6%8E%A7%E9%80%9A%E8%B7%AF%22%5D%0A%20%20NAND%20--%3E%20TS%5B%22%E4%B8%89%E6%80%81%EF%BC%9A%E5%8F%AF%E9%AB%98%E9%98%BB%22%5D%0A%20%20TS%20--%3E%20BUS%5B%22%E4%BA%92%E6%96%A5%E9%A9%B1%E5%8A%A8%E7%9A%84%E7%BA%BF%22%5D%0A%20%20BUS%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%97%A8%E6%97%B6%E5%BB%B6%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了高阻，组合连接不再只是门输出对门输入：还可以把多块的输出接到同一点再选通。后课寄存器堆读口、外设总线都靠这层。功能上仍可用 NAND 网模拟 MUX，面积与走线不同。传输门本身几乎不恢复电平，长链要插反相器——这是延迟课的负载，本课只承认。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 I/O 标准电压、漏极开路与上拉电阻的模拟细节（承认开漏是另一种「线与」）。不引入模拟乘法器式的传输特性。</p><p>后课默认：组合块除了推轨，还可以切断；总线必须互斥。任意组合功能至此都能落成门网或传输/三态网；时延下一课才量化。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>传输门是受控双向通路；三态输出可高阻。</li><li>同一节点多驱动必须互斥，否则争用。</li><li>\\(Z\\) 不是第三种逻辑值。</li><li>出处：Harris and Harris。</li></ul>',7))])}const S=s(h,[["render",c]]);export{T as __pageData,S as default};
